
INSERT INTO public.reviews (name, email, rating, feedback, sentiment, approved, created_at) VALUES
('Zara Padilla Jr', 'zara.pj@email.com', 5, 'The quattro stagioni pizza is a work of art. Four sections, four flavors, one amazing experience!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Andrei Manalo', 'andrei.m@email.com', 4, 'Really loved the smoked salmon pizza. Light, fresh, and the capers add a nice tangy pop.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Bianca Gutierrez', 'bianca.g@email.com', 5, 'The panna cotta dessert is the perfect ending to a pizza feast. Silky smooth and not too sweet.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Carlo Salazar', 'carlo.s@email.com', 4, 'The jalapeño poppers are dangerously addictive. Crispy, cheesy, spicy. Perfect bar snack with beer.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Dina Rivera', 'dina.r@email.com', 5, 'My go-to for comfort food. The meat lovers deep dish is hearty, cheesy, and absolutely divine.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Ernesto Santos', 'ernesto.s@email.com', 5, 'The cinnamon sugar pizza dessert is incredible! Sweet, warm, and the perfect shareable treat.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Fatima Torres', 'fatima.t@email.com', 4, 'The wrap options are a nice alternative to pizza. Had the chicken Caesar wrap and it was fresh and filling.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Gonzalo Reyes', 'gonzalo.r@email.com', 5, 'Pizza Volante has ruined other pizza places for me. Nothing else compares now. That''s how good it is.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Hazel Mendoza', 'hazel.m@email.com', 5, 'The kids menu is actually good here! Not just reheated nuggets but real mini pizzas with quality ingredients.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Ignacio Garcia', 'ignacio.g@email.com', 4, 'Solid neighborhood gem. The type of place where everybody knows your name. Great food, better people.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Juliana Bautista', 'juliana.b@email.com', 5, 'The hand-tossed dough is so light and airy. You can eat three slices without feeling heavy. Masterfully made!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Kirk Fernandez', 'kirk.f@email.com', 4, 'Great place to take clients. Professional enough for business but casual enough to be comfortable.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Lilia Lim', 'lilia.l@email.com', 5, 'The fresh pasta is cooked to order and you can tell. Al dente perfection every single time!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Miguel Aquino', 'miguel.a@email.com', 5, 'The combination of crispy fried chicken with creamy mashed potatoes and gravy is unbeatable. Comfort food at its finest!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Nelly Villanueva', 'nelly.v@email.com', 4, 'Really appreciate the contactless delivery option. Pizza arrives safely and still hot. Great system!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
-- More neutral
('Octavio Dela Cruz', 'octavio.dc@email.com', 3, 'Had lunch here. Food arrived in reasonable time. Pizza was warm. Taste was acceptable. Just average.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
('Patricia Tan', 'patricia.t@email.com', 3, 'The breadsticks are okay. Nothing remarkable about them. The pizza was similarly unremarkable.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
('Quirino Gomez', 'quirino.g@email.com', 3, 'It fills you up. That''s about the best compliment I can give. Standard, no-frills pizza.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
('Rosario Ramos', 'rosario.r@email.com', 3, 'The menu is big but nothing really stands out. Everything is just okay. Not bad, not memorable.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
('Silvio Navarro', 'silvio.n@email.com', 3, 'Pizza was decent. Wouldn''t go out of my way for it but wouldn''t refuse it either. Middle ground.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
('Teresita Ocampo', 'teresita.o@email.com', 3, 'Just a normal pizza joint. Clean, serviceable, nothing fancy. Does what it needs to do.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
('Ugo Castillo', 'ugo.c@email.com', 3, 'The pepperoni pizza was fine. I''ve had better but this was acceptable for the price point.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
('Viola Flores', 'viola.f@email.com', 3, 'Standard dine-in experience. Nothing to complain about but also nothing to get excited about.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
('Wilma Dizon', 'wilma.d@email.com', 3, 'The salad was fresh at least. The pizza was generic. Overall an average dining experience.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
('Xander Soriano', 'xander.s@email.com', 3, 'Picked up takeout on the way home. Pizza was lukewarm by the time I got there but tasted okay.', 'neutral', true, now() - interval '1 day' * floor(random() * 60)),
-- More negative
('Yuri Evangelista Jr', 'yuri.ej@email.com', 2, 'The pizza was so oily my fingers were dripping. Had to use five napkins per slice. Not enjoyable.', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
('Zuleika Padilla', 'zuleika.p@email.com', 1, 'Asked for mushroom pizza, got ham. Told them about the mistake and they said they''d charge extra to fix it. Outrageous!', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
('Alfredo Manalo', 'alfredo.m@email.com', 2, 'The pasta was drowning in sauce. Couldn''t even taste the noodles. Way too much sauce.', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
('Betty Gutierrez', 'betty.g@email.com', 1, 'Two hour delivery time on a weeknight. The food was ice cold. This is completely unacceptable.', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
('Clemente Salazar', 'clemente.s@email.com', 2, 'The dining area was freezing cold. Asked them to adjust the AC but nothing changed. Food was below average.', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
('Delia Rivera', 'delia.r@email.com', 1, 'Found a band-aid in my salad. I wish I was joking. Absolutely horrifying. Will never return.', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
('Esteban Santos', 'esteban.s@email.com', 2, 'The happy hour specials are misleading. Fine print says it''s only for dine-in, small pizzas, weekdays only. Deceptive.', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
('Felipa Torres', 'felipa.t@email.com', 1, 'Cockroach in the bathroom. When I told the staff they just said "oh." No urgency, no apology. Disgusting.', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
('Gaspar Reyes', 'gaspar.r@email.com', 2, 'The crust tastes like it was pre-made and frozen. No freshness to it at all. Very industrial taste.', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
('Herminia Mendoza', 'herminia.m@email.com', 1, 'They gave us a table right next to the kitchen door. Hot air blasting every time it opened. Staff ignored our request to move. Terrible.', 'negative', true, now() - interval '1 day' * floor(random() * 60)),
-- Final positive to round out
('Iván Garcia Jr', 'ivan.gj@email.com', 5, 'Perfect pizza for game night! Ordered 6 pizzas for the boys and every single one was devoured. Quality stuff!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Juana Bautista', 'juana.b@email.com', 4, 'The soup and pizza lunch combo is my midweek treat. Mushroom soup with garlic bread and a slice. Yum!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Karlo Fernandez', 'karlo.f@email.com', 5, 'Pizza Volante makes the best dipping sauces! The garlic butter one is absolutely legendary.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Lucinda Lim', 'lucinda.l@email.com', 5, 'My vegetarian friends finally have a pizza place they love! The veggie options here are creative and delicious.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Mateo Aquino', 'mateo.a@email.com', 4, 'Really enjoy their seasonal specials. The current holiday pizza with cranberry and turkey is surprisingly tasty!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Natasha Villanueva', 'natasha.v@email.com', 5, 'The service here is what sets them apart. Friendly, efficient, and they genuinely care about your experience.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Orlando Dela Cruz', 'orlando.dc@email.com', 5, 'Pizza Volante''s new truffle oil drizzle option is genius! Elevates any pizza to gourmet level. Amazing idea!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Paloma Tan', 'paloma.t@email.com', 4, 'The mozzarella is always perfectly melted and stretchy. That cheese pull is everything!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Ramiro Gomez', 'ramiro.g@email.com', 5, 'Their new chicken parmesan pizza is the best new item on any menu anywhere. Bold claim but it''s true!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Selena Ramos', 'selena.r@email.com', 5, 'After trying Pizza Volante, my family refuses to eat pizza anywhere else. It''s that good. Five stars forever!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Tito Navarro', 'tito.n@email.com', 4, 'The outdoor dining setup is beautiful in the evening. String lights, comfortable seating, and amazing pizza under the stars.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Uriel Ocampo', 'uriel.o@email.com', 5, 'Every ingredient tastes fresh. The vegetables are crisp, the meats are quality, and the cheese is real. No shortcuts here!', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Viviana Castillo', 'viviana.c@email.com', 4, 'Great happy hour deals! Half-price appetizers and the garlic knots are already amazing at full price.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('William Flores Jr', 'william.fj@email.com', 5, 'The focaccia bread here is heavenly! Olive oil, rosemary, sea salt - simple but so delicious as a starter.', 'positive', true, now() - interval '1 day' * floor(random() * 60)),
('Ximena Dizon Jr', 'ximena.dj@email.com', 5, 'My whole department agrees - Pizza Volante is the best pizza in town. And we''ve tried them all!', 'positive', true, now() - interval '1 day' * floor(random() * 60));
